"""Device database loaded from ``openrazer_mice.json`` and ``openrazer_other.json`` (generated by ``tools/import_openrazer.py``)."""
from __future__ import annotations

import functools
import json
from dataclasses import dataclass, field, replace
from importlib import resources


@dataclass(frozen=True)
class Command:
    fn: str  # OpenRazer builder function name (first named builder of the body)
    txn: int  # transaction id
    # every builder call of the body in source order; raw packets as "raw:0xAA/0xBB/0xCC".
    # More than one step (or a raw step) means a multi-packet sequence.
    steps: tuple[str, ...] = ()
    # constant arguments of the (single) builder call, resolved to numbers; "*" marks a value
    # supplied at run time (colour, level ...). Only recorded for non-mouse devices.
    args: tuple[int | str, ...] = ()

    def __post_init__(self) -> None:
        if not self.steps:
            object.__setattr__(self, "steps", (self.fn,))


@dataclass(frozen=True)
class DeviceInfo:
    model: str
    name: str
    pids: dict[int, str]  # PID -> "wired" | "wireless" | "receiver" | "bluetooth"
    dpi_max: int
    poll_rates: tuple[int, ...]
    features: frozenset[str]
    zones: dict[str, tuple[str, ...]]
    protocol: dict[str, Command]
    interface: int = 0
    verified: bool = False
    # protocol/features above hold only what is identical for ALL PIDs; per-PID additions/differences:
    pid_protocol: dict[int, dict[str, Command]] = field(default_factory=dict)
    pid_features: dict[int, frozenset[str]] = field(default_factory=dict)
    # "mouse" | "keyboard" | "keypad" | "headset" | "mousemat" | "accessory" | "dock" | "other"
    kind: str = "mouse"

    def for_pid(self, pid: int) -> DeviceInfo:
        """Flattened view for one PID: common entries plus that PID's own, pid_* emptied."""
        if pid not in self.pids:
            raise KeyError(pid)
        return replace(
            self,
            protocol={**self.protocol, **self.pid_protocol.get(pid, {})},
            features=self.features | self.pid_features.get(pid, frozenset()),
            pid_protocol={},
            pid_features={},
        )

    def __hash__(self) -> int:  # dict fields: hash on identity-defining model slug
        return hash(self.model)


def _commands(d: dict) -> dict[str, Command]:
    return {k: Command(c["fn"], c["txn"], tuple(c.get("steps", ())), tuple(c.get("args", ()))) for k, c in d.items()}


def _from_json(d: dict) -> DeviceInfo:
    return DeviceInfo(
        model=d["model"],
        name=d["name"],
        pids={int(p, 16): k for p, k in d["pids"].items()},
        dpi_max=d["dpi_max"],
        poll_rates=tuple(d["poll_rates"]),
        features=frozenset(d["features"]),
        zones={z: tuple(e) for z, e in d["zones"].items()},
        protocol=_commands(d["protocol"]),
        interface=d.get("interface", 0),
        verified=d.get("verified", False),
        pid_protocol={int(p, 16): _commands(c) for p, c in d.get("pid_protocol", {}).items()},
        pid_features={int(p, 16): frozenset(f) for p, f in d.get("pid_features", {}).items()},
        kind=d.get("kind", "mouse"),
    )


def _read(name: str) -> dict[str, DeviceInfo]:
    text = resources.files("razertux.devices").joinpath(name).read_text(encoding="utf-8")
    return {d["model"]: _from_json(d) for d in json.loads(text)["devices"]}


@functools.cache
def _load() -> dict[str, DeviceInfo]:
    return _read("openrazer_mice.json")


@functools.cache
def _load_other() -> dict[str, DeviceInfo]:
    return _read("openrazer_other.json")


def load_devices() -> dict[str, DeviceInfo]:
    """All known mice keyed by model slug (a fresh dict; the DeviceInfo values are shared)."""
    return dict(_load())


def load_all_devices() -> dict[str, DeviceInfo]:
    """Mice plus every other Razer device kind, keyed by model slug."""
    return {**_load(), **_load_other()}


@functools.cache
def _pid_index() -> dict[int, DeviceInfo]:
    return {pid: d for d in _load().values() for pid in d.pids}


@functools.cache
def _pid_index_any() -> dict[int, DeviceInfo]:
    return {pid: d for d in (*_load().values(), *_load_other().values()) for pid in d.pids}


def by_pid(pid: int) -> DeviceInfo | None:
    """Mouse lookup (unchanged); see ``by_pid_any`` for every device kind."""
    return _pid_index().get(pid)


def by_pid_any(pid: int) -> DeviceInfo | None:
    return _pid_index_any().get(pid)


def kind_by_pid(pid: int) -> str | None:
    d = _pid_index_any().get(pid)
    return d.kind if d else None
